const DeathPassiveInfo* ScriptSession::deathPassiveInfo(std::uint32_t ability,unsigned level){
    auto key=std::pair{ability,level};if(auto found=deathPassives_.find(key);found!=deathPassives_.end())return found->second?&*found->second:nullptr;auto& data=definitions();auto code=data.field(ability,"AbilityData","code",ObjectData::name(ability));std::optional<DeathPassiveInfo> result;
    if(level && data.ability(ability) && (code=="AOre" || code=="ACrn" || code=="AIrc" || code=="Aphx")){result.emplace();auto& d=*result;d.ability=ability;d.level=level;auto field=[&](const char* name){return data.number(ability,"AbilityData",std::string(name)+std::to_string(level));};d.kind=code=="Aphx"?DeathPassiveKind::Phoenix:code=="AIrc"?DeathPassiveKind::ItemReincarnation:DeathPassiveKind::Reincarnation;d.delay=d.kind==DeathPassiveKind::Phoenix?field("HeroDur"):field("DataA");d.cooldown=field("Cool");if(d.kind==DeathPassiveKind::ItemReincarnation){d.health=field("DataB");d.mana=field("DataC");}if(d.kind==DeathPassiveKind::Phoenix){auto normal=data.field(ability,"AbilityData","DataA"+std::to_string(level)),egg=data.field(ability,"AbilityData","UnitID"+std::to_string(level));if(normal.size()!=4 || egg.size()!=4 || !data.contains(ObjectData::code(normal)) || !data.contains(ObjectData::code(egg)))throw std::runtime_error("Phoenix requires source bird and egg types");d.normalType=ObjectData::code(normal);d.eggType=ObjectData::code(egg);}for(auto value:{d.delay,d.cooldown,d.health,d.mana})if(!std::isfinite(value) || value>1000000)throw std::runtime_error("Death passive parameter outside supported range");if(d.delay<0 || d.delay>86400 || d.cooldown<0 || d.cooldown>86400 || d.health<0 || d.mana<-1)throw std::runtime_error("Invalid source death passive timing or restoration");}
    auto found=deathPassives_.emplace(key,std::move(result)).first;return found->second?&*found->second:nullptr;
}
void ScriptSession::initializeDeathRestart(UnitState& u){if(u.illusion || u.removing || u.phoenixCycle || number(u.life)<=0)return;for(auto [ability,level]:u.abilities)if(level>0)if(auto d=deathPassiveInfo(ability,unsigned(level));d && d->kind==DeathPassiveKind::Phoenix && u.type==d->eggType){u.phoenixCycle=PhoenixCycle{*d,d->delay};deathRestartActors_.insert(u.handle);return;}}
void ScriptSession::clearDeathRestart(UnitState& u){if(u.rebirth){for(auto effect:u.rebirth->visuals)destroyEffect(effect);u.rebirth.reset();}u.phoenixCycle.reset();deathRestartActors_.erase(u.handle);}
bool ScriptSession::cancelDeathActivities(UnitState& u){
    auto dead=[&]{return alive(u.handle,NativeKind::Unit) && !u.removing && number(u.life)<=0;};cancelUnsummon(u);cancelHeroRevival(u.handle);if(!dead())return false;cancelBuildingRevivals(u.handle);if(!dead())return false;clearAuras(u);releaseAuraSource(u.handle);for(auto& [id,b]:u.buffs)releaseBuff(b);u.buffs.clear();cancelCombat(u);if(!dead())return false;releaseBuilder(u.handle,false);if(!dead())return false;releaseMine(u);if(!dead())return false;releaseCargo(u);if(!dead())return false;u.route.clear();u.waypoint=0;u.currentOrder=0;u.holding=false;u.animation="Death";u.animationTime=0;u.animationIndex.reset();u.animationQueue.clear();unitFootprint(u);++fogRevision_;return true;
}
bool ScriptSession::tryDeathRestart(std::uint32_t id){
    auto u=units_.at(id);if(u->phoenixCycle){clearDeathRestart(*u);return false;}if(u->rebirth || u->illusion || u->building || u->removing || u->exploded || (u->timedLife && u->timedLife->remaining<=0))return false;const DeathPassiveInfo* chosen=nullptr;std::uint32_t itemId=0;
    for(auto [ability,level]:u->abilities)if(level>0){auto available=config_.players[u->owner].abilityAvailable.find(ability);if(available!=config_.players[u->owner].abilityAvailable.end() && !available->second)continue;auto d=deathPassiveInfo(ability,unsigned(level));if(!d || d->kind==DeathPassiveKind::ItemReincarnation || (d->kind==DeathPassiveKind::Phoenix && u->type!=d->normalType) || spellCooldown(id,ability)>0)continue;chosen=d;break;}
    if(!chosen && inventoryFlag(*u,"DataC"))for(auto held:u->inventory){if(!held || !alive(held,NativeKind::Item) || items_.at(held)->holder!=id)continue;for(auto ability:itemAbilities(items_.at(held)->type)){auto d=deathPassiveInfo(ability,1);if(!d || d->kind!=DeathPassiveKind::ItemReincarnation)continue;auto item=items_.at(held);if(item->charges<=0 && definitions().number(item->type,"ItemData","uses")>0)continue;auto group=definitions().field(item->type,"ItemData","cooldownID",ObjectData::name(ability));auto cd=u->itemCooldowns.find(group);if(cd!=u->itemCooldowns.end() && cd->second>simulationTime_)continue;chosen=d;itemId=held;break;}if(chosen)break;}
    if(!chosen)return false;auto d=*chosen;if(d.kind==DeathPassiveKind::Phoenix){u->phoenixCycle=PhoenixCycle{d,d.delay};deathRestartActors_.insert(id);if(!cancelDeathActivities(*u) || !u->phoenixCycle)return true;u->life=real(1);if(!changeUnitForm(id,d.eggType,0,false) || !alive(id,NativeKind::Unit) || u->removing || !u->phoenixCycle || number(u->life)<=0)return true;u->life=u->maxLife;u->mana={};u->flyHeight=u->targetFlyHeight=definitions().number(d.eggType,"UnitData","moveHeight");u->flyRate=0;u->animation="Stand";u->animationTime=0;unitFootprint(*u);++fogRevision_;return true;}
    RebirthState state;state.definition=d;state.remaining=d.delay;state.manaBefore=number(u->mana);u->rebirth=std::move(state);deathRestartActors_.insert(id);if(itemId){auto held=items_.at(itemId);if(held->charges>0)--held->charges;u->itemCooldowns[definitions().field(held->type,"ItemData","cooldownID",ObjectData::name(d.ability))]=simulationTime_+d.cooldown;}else u->spellCooldowns[d.ability]=simulationTime_+d.cooldown;
    if(!cancelDeathActivities(*u) || !u->rebirth)return true;beginCorpse(*u);u->corpse->flags=0;SpellInfo art;art.ability=d.ability;u->rebirth->visuals=spellVisual(art,"EffectArt",0,{u->x,u->y},false);if(itemId && alive(itemId,NativeKind::Item)){auto held=items_.at(itemId);ScriptContext context;context.manipulatedItem=itemId;unitEvent(id,50,87,context);if(alive(itemId,NativeKind::Item) && held->charges==0 && definitions().number(held->type,"ItemData","perishable")!=0)removeItem(itemId);}return true;
}
void ScriptSession::deathRestartsTick(double delta){
    std::vector<std::uint32_t> actors(deathRestartActors_.begin(),deathRestartActors_.end());for(auto id:actors){if(!alive(id,NativeKind::Unit)){deathRestartActors_.erase(id);continue;}auto u=units_.at(id);if(u->removing){clearDeathRestart(*u);continue;}if(u->rebirth){if(number(u->life)>0){clearDeathRestart(*u);continue;}if(u->paused)continue;u->rebirth->remaining=std::max(0.,u->rebirth->remaining-delta);if(u->rebirth->remaining>0 || number(u->maxLife)<=0)continue;auto at=formLanding(*u,u->type);if(!at)continue;auto state=*u->rebirth;clearDeathRestart(*u);u->x=at->x;u->y=at->y;u->combat.home=*at;float hp=state.definition.kind==DeathPassiveKind::Reincarnation?number(u->maxLife):std::clamp(state.definition.health,1.f,number(u->maxLife));u->mana=real(state.definition.kind==DeathPassiveKind::Reincarnation?number(u->maxMana):std::clamp(state.definition.mana<0?state.manaBefore:state.definition.mana,0.f,number(u->maxMana)));unitLife(runtime_.handle("unit",id),real(hp));continue;}
        if(u->phoenixCycle){if(number(u->life)<=0 || u->type!=u->phoenixCycle->definition.eggType){clearDeathRestart(*u);continue;}if(u->paused)continue;u->phoenixCycle->remaining=std::max(0.,u->phoenixCycle->remaining-delta);if(u->phoenixCycle->remaining>0)continue;auto d=u->phoenixCycle->definition;auto at=formLanding(*u,d.normalType);if(!at)continue;u->x=at->x;u->y=at->y;if(!changeUnitForm(id,d.normalType,0,false) || !alive(id,NativeKind::Unit) || u->removing || !u->phoenixCycle || number(u->life)<=0)continue;clearDeathRestart(*u);u->life=u->maxLife;u->mana=u->maxMana;u->flyHeight=u->targetFlyHeight=definitions().number(d.normalType,"UnitData","moveHeight");u->flyRate=0;u->animation="Stand";u->animationTime=0;u->combat.home=*at;unitFootprint(*u);++fogRevision_;continue;}deathRestartActors_.erase(id);
    }
}
void ScriptSession::summonPhoenix(std::uint32_t id,const SpellInfo& s,unsigned owner){
    if(!alive(id,NativeKind::Unit))return;auto caster=units_.at(id);auto point=WorldPoint{caster->x,caster->y};if(!summonPoint(point,s.summonType,caster->collision+32))return;std::vector<std::uint32_t> previous;for(auto& [handle,u]:units_)if(u->summoner==id && u->summonAbility==s.ability && number(u->life)>0)previous.push_back(handle);for(auto handle:previous){if(!alive(id,NativeKind::Unit) || caster->removing || number(caster->life)<=0 || caster->owner!=owner)return;removeUnit(handle);}for(unsigned count=0;count<s.summonCount;++count){if(!alive(id,NativeKind::Unit) || caster->removing || number(caster->life)<=0 || caster->owner!=owner)return;auto at=summonPoint(point,s.summonType,caster->collision+32);if(!at)break;auto h=createUnit(owner,s.summonType,at->x,at->y,caster->facing);if(!alive(h.bits,NativeKind::Unit))continue;auto u=units_.at(h.bits);u->summoner=id;u->summonAbility=s.ability;spellVisual(s,"Specialart",h.bits,*at);ScriptContext context;context.summoningUnit=id;context.summonedUnit=h.bits;unitEvent(id,47,84,context);}
}
